import{_ as n,c as t,o as s,j as o,Y as r,t as i}from"./chunks/framework.BNTND4LZ.js";const w=JSON.parse('{"title":"network_namespaces | x-cmd man (man7) | overview of Linux network namespaces","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | network_namespaces - overview of Linux network namespaces","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"network_namespaces | x-cmd man (man7) | overview of Linux network namespaces"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | network_namespaces - overview of Linux network namespaces"}]]},"headers":[],"params":{"isMan":true,"man":"network_namespaces","category":"man7","desc":"overview of Linux network namespaces"},"relativePath":"man7/network_namespaces.md","filePath":"man7/[man].md"}'),c={name:"man7/network_namespaces.md"},m={class:"visually-hidden"};function p(a,e,d,l,h,g){return s(),t("div",null,[o("h1",m,i(a.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>network_namespaces - overview of Linux network namespaces</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Network namespaces provide isolation of the system resources associated with networking: network devices, IPv4 and IPv6 protocol stacks, IP routing tables, firewall rules, the <em>/proc/net</em> directory (which is a symbolic link to <em>/proc/<em>pid</em>/net</em>), the <em>/sys/class/net</em> directory, various files under <em>/proc/sys/net</em>, port numbers (sockets), and so on. In addition, network namespaces isolate the UNIX domain abstract socket namespace (see <strong>unix</strong>(7)).</p><p>A physical network device can live in exactly one network namespace. When a network namespace is freed (i.e., when the last process in the namespace terminates), its physical network devices are moved back to the initial network namespace (not to the namespace of the parent of the process).</p><p>A virtual network (<strong>veth</strong>(4)) device pair provides a pipe-like abstraction that can be used to create tunnels between network namespaces, and can be used to create a bridge to a physical network device in another namespace. When a namespace is freed, the <strong>veth</strong>(4) devices that it contains are destroyed.</p><p>Use of network namespaces requires a kernel that is configured with the <strong>CONFIG_NET_NS</strong> option.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nsenter</strong>(1), <strong>unshare</strong>(1), <strong>clone</strong>(2), <strong>veth</strong>(4), <strong>proc</strong>(5), <strong>sysfs</strong>(5), <strong>namespaces</strong>(7), <strong>user_namespaces</strong>(7), <strong>brctl</strong>(8), <strong>ip</strong>(8), <strong>ip-address</strong>(8), <strong>ip-link</strong>(8), <strong>ip-netns</strong>(8), <strong>iptables</strong>(8), <strong>ovs-vsctl</strong>(8)</p>',9))])}const u=n(c,[["render",p]]);export{w as __pageData,u as default};
